parameters.functionCode:
// Evaluates which appointments are due for 24-hour reminder
const items = $input.all();
const results = [];
const now = new Date().getTime();

for (const item of items) {
  const resultsList = item.json.results || [];
  for (const bkg of resultsList) {
    const startTime = new Date(bkg.start_time).getTime();
    const hoursDiff = (startTime - now) / (1000 * 60 * 60);

    // Send reminder if between 23 and 25 hours away
    if (hoursDiff >= 23 && hoursDiff <= 25) {
      results.push({ json: bkg });
    }
  }
}
return results;

